NIGHT_LOADED({"seed":1004,"generated_at":"2026-10-21T06:00:00Z","chain":[1,3,2,4,5],"frame":{"collector":"J.J.V.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.J.V.","note_final":"Goed opgeborgen. Morgen om negen. — J.J.V.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.J.V.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.J.V.","initials":"J.J.V.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.J.V.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":5,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0068,"rank":0.0948,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000604","role":"target","render":{"description":"Dringend advies om een brandverzekering af te sluiten, want iemand heeft het huis in brand zien staan. Een tijd later brandt het huis af.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42967","original":"[4.]\nMijn opa kwam ook eens bij buurman Scheper. \"Hest dien hoes in de brandkaaste Beernd?\"\n\"Nee,\" zei Beernd.\n'n Paor dagen later opa er weer heen.\n\"Beernd, hest 't hoes in de brandkaaste?\"\n\"Nee, nog nich.\"\n\"Dou hum d'r doadeluk in, want ik heb 't branden zain.\"\nEen paar maanden later, daor ging 't huis.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.0987,"rank":0.2025,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ051006","role":"member","render":{"description":"Een vader waarschuwt zijn kinderen 's nachts nooit middenop de weg te lopen. Ze kunnen immers op een lijkstoet stuiten.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25083","original":"Heit woe noait lije, dat wy froeger by jountiid of by nacht midden op 'e wei roannen. Sels gong er ek altyd yn 'e berm lâns. Men koe ris tsjin in lykwein oprinne, wie syn sizzen altyd.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"CJ112406","role":"member","render":{"description":"Vanwege lijkstaties die de ruimte nodig hebben is het goed om 's nachts niet midden op de weg te lopen.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/30112","original":"Noait mat men by nacht midden op 'e wei rinne, fanwegen in lykstaesje, dy't altyd paed ha mat en dy't dan wolris tsjin jin oanstompe kin.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c3","story_id":"LINSSEN009801","role":"intruder","render":{"description":"Vermijden van vuurbollen en vuurmannen; weerwolf laat zich dragen.","place":"Koningsbosch","prov":"L.","year":1965,"code":"SINSAG 0801","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/209005","original":"Vuurbollen en vuurman, weerwolf\nIn zijn jeugd tot zijn 25e jaar woonde verteller in een Duits grensplaatsje (zie boven). Daar werden omtrent vuurbollen en vuurmannen angstaanjagende verhalen verteld, evenals hier te Koningsbosch. Men moest vermijden in hun nabijheid te komen. De weerwolf sprong de mensen s avonds op de nek en liet zich dan een eindweegs dragen.","lang":"Standaardnederlands","front":"original"},"home":"cab:3"},{"id":"c4","story_id":"CJ034606","role":"member","render":{"description":"Je moet nooit middenop de weg lopen, omdat je opzijgedreven kan worden door een lijkstoet.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22678","original":"Der woarde ús al hiel jong leard, noait midden op 'e wei to rinnen. Hwant it koe gebeure dat der in lykstaesje oankom en dan woarde men oan kant set.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Koningsbosch hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":3},"on_success":{"trail_note":0,"unlock_cabinet":3,"stack":["c1","c2","c4"]}},{"id":"1-3","type":"R1","difficulty":1.0981,"rank":0.0837,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ022401","role":"omen","render":{"description":"Een vrouw had vijf weken voor een brand het huis al zien afbranden.","place":"Harkema","prov":"Fr.","year":1967,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20948","original":"Myn wiif Sjouk hat it hûs fan Ate en Ynsk hjir yn 'e Harkema sa'n fiif wike foar dat it echt opbrânde al yn 'e brân sjoen. \"Och Heare,\" sei se, \"Ate en Ynke har hûs brânt op!\"","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ057502","role":"omen","render":{"description":"Een man kwam bij zijn zieke moeder, en zag een doodskist in haar huis. Maar zijn moeder was niet dood en ze bleef nog vijf jaar in leven. Later is de doodskist er echt gekomen.","place":"Houtigehage","prov":"Fr.","year":1968,"code":"SINSAG 0483","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25868","original":"Heit syn mem wie o sa min. Mem wie nei har ta gong. Heit kom even letter. Hy wie oan 'e doar ta, doe stie dêr de kiste al, mei 't kleed der oerhinne. It kleed waeide in bytsje op, doe't de doar iepenkom.\nDoe't er yn 'e keamer stapte, wìe beppe der noch. Sy hat noch wol fiif jier leefd. Mar hwat heit foarút sjoen hie kom dêrom letter wol krektsa út.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ058207","role":"omen","render":{"description":"Een man zag ergens lichten, maar in werkelijkheid was er niets. Vijf jaar later is er een tram gekomen.","place":"Opende","prov":"Gr.","year":1969,"code":"SINSAG 0492","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25990","original":"De tram is hjir kom yn 1911. Mar fiif jier earder seach myn swager de ljochten al. By Likele Pama - tichte by de Wilhelmina-hoeve - wie in wissel. Dêr seach hy de tram doe al rikjen. Hindrik de Jong hiet myn swager.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","5 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":5},"on_success":{"chime":5,"digit":{"value":5,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P4","difficulty":1.7036,"rank":0.7241,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"YPFOE088","role":"top","render":{"description":"Een boer heeft twee zonen. De ene is 's ochtends niet van het bed te krijgen, de andere moet al het werk doen. Hij is dat","place":"Goutum","prov":"Fr.","year":1974,"code":"SINSAG 0311","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12173","half":"top"},"home":"2-1"},{"id":"c2","story_id":"VODA_035_14","role":"distractor","render":{"description":"De oude knecht is bang. Een jonge, onverschrokken knecht biedt aan om vanaf nu de paarden naar de wei te brengen en weer op te halen. Op een dag ziet ook de jonge knecht een brandend kaarsje op het damhek en twee zwevende dames. De paarden zijn onrustig. De knecht slaat het kaarsje van het hek en de twee dames zijn meteen verdwenen. De paarden zijn weer kalm. Vanaf dat moment wordt de jonge knecht echter nacht na nacht gekweld door de witte dame die haar lichtje terug wil en na zes weken sterft hij hierdoor.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c3","story_id":"YPFOE088","role":"bottom","render":{"description":"op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c4","story_id":"OIRSCHOT095","role":"distractor","render":{"description":"De dochter deden hun rok in de broeken en een doek om heet haar. De mensen zagen rondom het kasteel witte vrouwen, waarvan ze dachten dat het spoken waren. Maar dat waren waarschijnlijk de kasteelvrouw met haar dochters.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c5","story_id":"LAAN004a","role":"distractor","render":{"description":"Op de grens van Slochteren en Schildwolde wandelden ze een eikenlaan op en neer in lange, witte gewaden. Zij zijn nooit overdag gezien, maar bang waren ze niet. Ze waren in griezelige steden en op kerkhoven. Ook waren ze altijd op plaatsen waar iets gebeurd was.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c6","story_id":"CJ001413","role":"distractor","render":{"description":"Hij heeft zijn tante vermoord om haar geld en sinds die tijd spookt het er. Dit alles gebeurt dichtbij de plek waar het huis van sterke Hearke heeft gestaan.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c7","story_id":"ZEEUW054","role":"distractor","render":{"description":"Daar waren 3 koffers met op een 'n hond, op de 2e 'n leeuw met de sleutel van de 3e in zijn bek, die de man moet pakken. Hij durft 't niet en de vrouw neemt afscheid voor 100 jaar.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c8","story_id":"LYST293","role":"distractor","render":{"description":"Haar jurk is met veren bekleed. Dikwijls kan men 's morgens wat van die veertjes op de weg zien liggen. Haar aanwezigheid schijnt een noodlottige invloed te hebben.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c9","story_id":"LAAN005","role":"distractor","render":{"description":"Er was een widde juvver, wiens kleed te lang was, waardoor iedereen erover viel. Een ziever heeft die afgeknipt en sindsdien ging het hem en zijn familie altijd goed.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c10","story_id":"ZEEUW049","role":"distractor","render":{"description":"Sindsdien heeft men juffrouw Jenne niet meer gezien..","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c11","story_id":"LYST030","role":"distractor","render":{"description":"Als tegenprestatie moet ze naakt door de kerk rennen. Ze doet dit met tegenzin. Later is er op de grond die ze heeft gekregen, een wit wief te zien. Men is ervan overtuigt dat de geest van de vrouw daar nog rondspookt.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c12","story_id":"LYST265","role":"distractor","render":{"description":"De maaier slaat op de vlucht. De buurman van de maaier is van mening dat de man waarschijnlijk een stroper of smokkelaar heeft gezien met een wit laken om zich heen. Ook kan het iemand geweest zijn die jonge meisjes schrik aan wilde jagen.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c13","story_id":"LYST041","role":"distractor","render":{"description":"Ze schrikken heel erg omdat ze denken dat het de onheilbrengende gedaante van een wit wief is. Later zien ze dat de gedaante geen wit wief is maar en witte geit die met zijn poten tegen de boom aan staat te eten van de bladeren.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het bovenste stuk breekt midden in een zin af. Het onderste maakt hem af.","Het nummer is SINSAG 0311. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c3"},"on_success":{"fuse":["c1","c3"],"stack":["c1","c3"]},"found_card":{"card":"c3"}},{"id":"2-2","type":"P3","difficulty":1.2678,"rank":0.8234,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ063812","role":"member","render":{"description":"In Parken en in Rottefalle spoken witte wijven.","place":"Opende","prov":"Gr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/27145","original":"Hjir yn 'e Parken spoeken wite wiven en dat wie ek yn 'e Rottefalle it gefal.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c2","story_id":"KEUNING003002","role":"intruder","render":{"description":"Meisjes spoken 's nachts op de plaats waar ze zijn vermoord.","place":"Broeksterwâld","prov":"Fr.","year":1962,"code":null,"initials":"S.K.","url":"https://www.verhalenbank.nl/items/show/130952","original":"Ik arbeide op it sûkerijfebryk. Dêr fortsjinne ik twa goune yn de wike. Ik wier doe in jongfeint. Myn kameraten forgunden my dit ek noch. Op it Formanjepaed, hwer ik lâns moast nei it wurk, wierne troch in keardel twa famkes formoarde. Sont spûken dy dêr nachts altyd.","lang":"Fries","front":"original","uncatalogued":true},"home":"cab:4"},{"id":"c3","story_id":"CJ057303","role":"member","render":{"description":"Meerdere mensen hebben door het bos twee witte wijven gezien.","place":"Opende","prov":"Gr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25852","original":"Witte wiven gingen altyd door 't bos van Jild Dyk. En so ferdwenen se weer. 't Waren twee witte frouljuu.\nDit gebeurde faak. Forskeidene hebben se sien.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"CJ061710","role":"member","render":{"description":"Op de hei in Drenthe spoken witte wijven.","place":"Opende","prov":"Gr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/26899","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een spook.","De kaart over Broeksterwâld hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":2,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0371,"rank":0.4915,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"CJ020208","role":"sill","render":{"description":"Mensen zagen op een avond eens twee witte wijven.","place":"Jistrum","prov":"Fr.","year":1967,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20586","stain":"twee"},"home":"2-3"},{"id":"c2","story_id":"ENGELB_02_006","role":"card","render":{"description":"Populierhout gloeit bij goed weer. Een papieren zak wordt voor een spook aangezien.","place":"Rossum","prov":"Ov.","year":1970,"code":"SINSAG 0310","initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128393"},"home":"2-3"},{"id":"c3","story_id":"ZEEUW045","role":"card","render":{"description":"Een boerenzoon, die 's winters in de stad werkt, wordt altijd 's avonds bij het naar huis gaan vergezeld op de dijk door een witte juffrouw, die boven de grond zweefde en geen woord zei. Vlakbij de boerderij was ze ineens verdwenen.","place":"Terneuzen","prov":"Zl.","year":1923,"code":"SINSAG 0310","initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/38971","original":"Witte Juffers\n\nEen boerenzoon van een hofstede bij Terneuzen kwam altijd 's winters in de stad werken. 's Avonds bij het naar huis gaan, moest hij een eind den zeedijk volgen, en als hij maar een voet op den dijk gezet had, verscheen er een witte juffrouw naast hem. Ze raakte met haar voeten den grond niet, en als hij iets zei, gaf ze geen antwoord. Soms sloeg hij er naar, maar dan was ze verdwenen, om op hetzelfde oogenblik weer naast hem te loopen; maar als hij bij de hoeve kwam, was ze er ineenen niet meer.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c4","story_id":"OIRSCHOT002103","role":"card","render":{"description":"Om middernacht zien passanten een vrouw zonder hoofd.","place":"Haaren","prov":"N.-Br.","year":1967,"code":"SINSAG 0311","initials":"A.v.O.","url":"https://www.verhalenbank.nl/items/show/41651","original":"Vrouw zonder hoofd\nDa heb ik ok dikkuls heure vertelle deur m'n grotvaoder. \nDe boere ginge vruuger beer haole in den Bosch, en dan ginge ze deur de Essevoort. Dikkuls kwaome ze dan om 'n uur of twaolf terrug. En d'r kwaame ze 's naags 'n vrouw tege zonder hoofd. Nou, toen ze dà tegen iemand hadde verteld, zee die: nou da wil ik toch wel us zien. En ze ginge d'r ok um twaolf ure naor toe, en ze kwaame ze teuge. Hij ha zône schrik, toen ie ze werrekeluk zaag.","lang":"Brabants","front":"description"},"home":"2-3"},{"id":"c5","story_id":"LYST278","role":"card","render":{"description":"Een boerenknecht gaat een weddenschap aan dat hij het spit zal brengen naar de Witte Wieve. Een van hen achtervolgt hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel. Het Witte Wief kon niet sneller lopen, omdat ze problemen had met een van haar schoenen.","place":"Ootmarsum","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"P.H.v.d.M.","url":"https://www.verhalenbank.nl/items/show/13622","original":"Men vertelt dat ze woonden in De Hunenberg, een oud-saksische burg bij Ootmarsum.\nEen jonge boerenknecht had eens een weddenschap aangegaan, dat hij de Witte Wieve wel het braadspit durfde brengen. Hij reed te paard naar de burg en gooide het braadspit om de deur. \"Ik wol oe 't spit brenge.\" \"Zoa, dan zöl ie 't gebraod wên, mer eerst mo'k miene veters dicht hem.\" Ze was namelijk bezig haar schoenen vast te maken. De boerenknecht wachtte echter niet op haar komst, maar vloog weg, zo snel zijn jonge paard hem dit veroorloofde. Reeds spoedig hoorde hij achter zich de galop van een paard met 't witte wiefke erop. Hij spande zijn paard tot nog grotere snelheid aan. …","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ111314","role":"card","render":{"description":"Voor rondspokende witte juffers hoef je niet bang te zijn. De witte spookvrouwen kunnen verdreven worden, de zwarte niet.","place":"De Westereen","prov":"Fr.","year":1974,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29719","original":"Men heart wolris fan wite juffers dy't spoekje. Dêr hoeft men net bang foar to wêzen. Wyt kin fordreaun wurde, mar swart net.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een J.","Jistrum. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c1","object":"window","text":"Jistrum"},"on_success":{"digit":{"value":2,"card":"c1","word":"twee","stained":"c1"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":3,"drawers":[{"id":"3-1","type":"P5","difficulty":0.679,"rank":0.375,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"LYST274","role":"variant","render":{"description":"Knecht, die 's nachts in een wolf verandert, verdwijnt als de boer onder zijn bed een wolfshuid vindt en verbrandt.","place":"Drogteropslagen","prov":"Dr.","year":1937,"code":"SINSAG 0824","initials":"K.J.","url":"https://www.verhalenbank.nl/items/show/13538","original":"Vroeger was hier een knecht, die 's nachts in een wolf veranderde en het de mensen dan lastig maakte. Onder zijn bed vond de boer op zekere dag een wolfshuid en verbrandde die. Sedert was de knecht verdwenen.\n(Verteld door een zeventig-jarige).","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c2","story_id":"VVUNL301","role":"variant","render":{"description":"Een knecht wordt weerwolf door een leren riem, die hij verstopt. Deze wordt gevonden en in de oven verbrand; meteen komt de verdachte knecht te paard aansnellen, maar wordt tegengehoudcen en zegt als de riem verbrand is: \"Ik ben verlost!\"","place":"Echt","prov":"L.","year":1920,"code":"SINSAG 0824","initials":"F.S.S.","url":"https://www.verhalenbank.nl/items/show/35840","original":"De weerwolf \n\nOp de hoeve Bosscherhof woonde eertijds een knecht die een lederen riem bezat, welke de macht had, hem, indien hij hem omgordde, te betoveren als weerwolf. Geheimzinnig en zorgvuldig werd deze band telkenmale door de knecht verstopt en wat men ook deed, hoe men ook spiedde, men vond hem nooit. En geregeld hadden de mensen uit de omtrek, die laat huiswaarts keerden, de weerwolf te dragen. En ook iedereen herkende steeds de knecht. Men gaf elkander raad om wanneer men overvallen werd, de weerwolf op een of andere manier te prikken of te krab-ben tot hij bloed voelde of zag. Dan was men gered. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c3","story_id":"LINSSEN002605","role":"variant","render":{"description":"Knecht die om middernacht door velg in zwarte kat verandert, is verlost na verbranden van velg.","place":"Baexem","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208342","original":"Volgens tweede verteller was er op Nelishof te Tungelroy een knecht die elke nacht tussen twaalf en een uur afwezig was. Door een raampje ging hij naar buiten. Hij klom dan op de schansenhoop en kwam er als kat af. De boer had hem bespied en gemerkt dat boven op de schansenhoop een velg lag van een karwiel. Die had de boer daar niet neergelegd en hij zocht verband tussen de spokerij (zwarte kat) en dat karwiel.\nDit zou hij vernietigen als de knecht afwezig was. Op zekere dag had hij hem met schapen naar Antwerpen gestuurd. Toen hij een dag weg was stak de boer zijn bakoven aan en wierp de velg erin.\nOp hetzelfde moment verscheen de knecht en wilde de oven in. Het gelukte slechts met drie man om hem daarvan te weerhouden. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Limburg werd een dier gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.J.V.","summary":true},"home":"3-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1920.","Op die kaart staat een dier. Welk?"],"lock":{"kind":"word","salt":"e67b9b37a212ac81","accepted_hashes":["3a25aed4ae6a2b88fd8104a6d669ae039c7aa53fffd67c868b215408957684e1","5ab5a9ea626d4333562f672b4c01c2f575e1ed5653956823f72c3727facf1294","90d0c034394b32bcfb90737d0b0cf42a9252c215d372c2464988b08876840563","aec315d8baa6e650b5eccefcf911f26803023ea2f6d015bc17ef7aa4ab696d89","d32ab8def671fad75d76770d9b12fb17c76a593243955635e8d9e09042b076c0","f7da697f9a793c25fbfd5fecbe57a2886f0192b7bedfcd7daf55d34d9c35166e"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.0949,"rank":0.4963,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"VVUNL049","role":"member","render":{"description":"Elke avond na het eten gaat Sjang weg en komt pas heel laat terug. Op een keer volgen ze hem en zien hem iets uit een boom halen en even later was hij een weerwolf. De pastoor wordt gehaald en Sjang moet zijn spullen tevoorschijn halen. Er kwam een schapevacht en een rood stokje met rood lint uit; die worden in de oven verbrand, terwijl drie man Sjang in bedwang houden. Als alles verkoold is, zegt hij verlost te zijn.","place":"Kessel","prov":"L.","year":1952,"code":null,"initials":"J.N.","url":"https://www.verhalenbank.nl/items/show/35588","original":"De geplaagde herder \n\n't Gebeurde op 'Gravenhof' te Kessel, tussen 1860 en '70. Sjang van de Maas uit Neer was hier scheper; een onnozele, rustige kerel, die niemand kwaad deed, en elke dag zijn schapen hoedde. Maar na een tijdje maakten de boer en de boerin zich over hem ongerust. Elke avond na het eten verdween Sjang plotseling en keerde pas heel laat in de nacht weer huiswaarts. Dit werd zo verdacht dat men op een keer de knaap stilletjes achtervolgde... Men zag toen dat hij tot de holle boom liep, even voorbij het Annakapelletje; daar nam hij iets uit. Na enkele ogenblikken veranderde hij van gedaante, en stoof als schrikaanjagende weerwolf met een geweldige vaart weg. . . …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"CBOEK477","role":"intruder","render":{"description":"Een knecht moet in een weddenschap aantonen, dat hij de spit in de Witte Wieven-kuil durft te gooien. Hij gooit en daagt het witte wief uit, dat hem achtervolgt. Met paard en al springt de knecht over de onderdeur. Het witte wief gooit de spit, dat in de middelaar van de deur blijft zitten.","place":"Bathmen","prov":"Ov.","year":1892,"code":null,"initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/39631","original":"In de buurtschap Loo, op het erve Noever ging men een weddenschap aan met een knecht, dat hij het spit niet durfde gooien in de Witte-wieven-kuul; deze bevond zich daar ergens in de buurt. Hij sprong te paard en joeg derwaarts, aldaar smeet hij het spit in de kuil met de woorden:\n\nWit wieven wit\nHier breng ik oe een spit\n(of: Wat heb ie'j op oe spit?)\n\nDaarop had het wit wief gezegd:\n\nA'j zoo lang wacht\nDak mien eene schoe toeknuppe\nEn de aander toerukke\nDan zal ie'j 't gebraad wezen.\n\nDe knecht rende toen in vliegenden vaart huiswaarts, achtervolgd door het wit wief en voor de achterdeur gekomen, was de bovendeur los en de onderdeur dicht, maar het paard was nogal vlug en sprong over de onderdeur. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c3","story_id":"ENGELS000115","role":"member","render":{"description":"Weerwolf bespringt 's avonds mensen; als helper bij werk; verandering in weerwolf door aantrekken verborgen jas, na verbranden jas bevrijding.","place":"Helden","prov":"L.","year":1962,"code":null,"initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/57969","original":"Weerwolven:\nMannen, die wat laat op de baan waren, werden, vooral in donkere, stormachtige nachten soms besprongen door de weerwolf. Dit spookdier met gloeiende ogen sprong hen op de rug, en klemde zich met de voorpoten om hun nek. Ze bleven zich als een zware last aan de verschrikte man klemmen totdat hij ergens een huis bereikte. In de Broekbeemd, tussen Onder-Eijndt en Zandberg, stond ergens een holle eiken knot of poesjt. Er was een man, die als weerwolf bekend werd. Hij had een aparte jas; als hij deze aantrok werd hij weerwolf. Na zijn nachtelijke tochten verborg hij deze jas in die holle “poesjt”. Zijn buurlui ontdekten dit, en staken de “poesjt” met de jas in brand. …","lang":"Standaardnederlands; Limburgs","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"KEMP298","role":"member","render":{"description":"Een pachter komt erachter dat een kleine scheper op zijn boerderij vermoedelijk een weerwolf is. Hij stuurt hem weg voor een dag en hij en zijn knechten ontdekken in een holle wilg een wolvenvel. Ze steken het thuis in brand. De scheper keert vervolgens in razend tempo terug en wil zijn vel teruggrijpen. Als dat niet lukt, vlucht de scheper naar de holle boom en is nooit meer teruggezien.","place":"Broek","prov":"L.","year":1925,"code":null,"initials":"I.S.","url":"https://www.verhalenbank.nl/items/show/43423","original":"Het weerwolfsvel verbrand\n\nBij de pachter van de boerderij bij het kasteel Geusselt onder Amby diende eens een scheper, een klein manneke, dat de naam had een weerwolf te zijn. 's Nachts was hij nooit in bed te vinden, maar 's morgens lag hij er weer in. De knechts van de hoeve hadden dat al dikwijls bemerkt.\nWijl dit zo opvallend was, werd zijn doen en laten gedurig bespied en zo bemerkte men dan ook dat hij, wanneer hij 's avonds uit zijn bed kroop, naar een weide ging, waar heel eenzaam een grote holle wilg stond. Daar verdween hij iedere keer in.\nOm het fijne van de zaak te achterhalen stuurde de pachter hem op zekere namiddag naar een dorp, dat meer dan drie uur van de hoeve lag, om daar koeien te kopen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Bathmen hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c1","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.0054,"rank":0.2821,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ044011","role":"card","render":{"description":"Een van zeven zonen is een weerwolf. Men moet nooit ruzie krijgen met een weerwolf, want dan maakt hij je dood. \nEen meisje naaide altijd bij andere mensen. Haar vrijer vroeg haar eens om een zakdoek. Ze gaf het hem, en buiten verscheurde hij het ding helemaal. Daarna was hij weer normaal. Hij bleek een weerwolf te zijn. Toen heeft het meisje het uitgemaakt.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0823","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/24049","original":"Ien fan sawn soannen wie in wjerwolf. As in wjerwolf jin kriget, makket er jin dea, seinen se froeger tsjin ús. Men mat der noait rûzje mei krije, sei in muoike yn 'e Westerein, dan pakke se jo.\nMyn wiif hat in kammeraetske hawn, dy naeide altyd by oare minsken. Dy hie forkearing mei in feint.\nOp in kear wie er by har, doe frege er har om har bûsdoek. Hja hie him de bûsdoek jown, mar doe hied er dy bûsdoek yn alle moster forskuord bûtendoar.\nLetter wie er wer goed west, mar 't is wol útrekke tusken dy beiden. Hwant hy wie in wjerwolf.\nHja hat it sels oan myn wiif forteld. Dat kammeraetske wenne oan it Wyldpaed.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c3","story_id":"LYST189","role":"door","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"ENGELS001721","role":"card","render":{"description":"Man moet twee dagen met weerwolf rondlopen.","place":"Grashoek","prov":"L.","year":1962,"code":"SINSAG 0801","initials":"G.G.E.","url":"https://www.verhalenbank.nl/items/show/210547","original":"Weerwolven:\nIk heb eens horen vertellen van een man in Kessel, die twee dagen met een weerwolf op zijn rug moest lopen. Hij werd hem eindelijk kwijt, door hem tussen twee dicht bijeen staande bomen af te wringen. Hij had de klauwsporen op zijn borst staan.\n\nVerslag 50, Omzetting van de verhalen, verteld door Leonardus Kluijtmans, Helden, doorgegeven onder no. L291-17, op 26-12-1962. Van Nederl. versie in plaatselijk dialect. Helden, 4 nov. 1969\nIch heb èns huuëre vertèlle van enne mins in Kèèssel, dè twieë daag mèt te wèèrwolf hei motten drage. Hè woord öm kwiet, dor öm tössen twieë buim, die kort bei-ein sjtonge, van de rök te vringe. Later hei ’n de klauwsjpóre nag op zien boorst staon.","lang":"Standaardnederlands; Limburgs","front":"description"},"home":"3-3"},{"id":"c5","story_id":"KOOIJMAN1182","role":"card","render":{"description":"Er woonde vroeger in Blokland een vrouw en die beweerde dat ze iedere avond de weerwolf buiten tekeer hoorde gaan tussen half elf en twaalf uur.","place":"Blokland","prov":"Utr.","year":1963,"code":"SINSAG 0804","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/72678","original":"De weerwolf, de weerwolf. Nou je 't zegt. D'r woonde vroeger in Blokland een vrouw. Die woonde daar op d'r eige alleen. En die vrouw die beweerde, ze hoorde iedere avond de weerwolf buite tekeergaan. Iedere avond tusse half elf en twaalf uur. Ze sloot alles d'r voor af.","lang":"Utrechts","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","3 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c3","object":"door","n":3},"on_success":{"digit":{"value":3,"card":"c1"},"stack":["c1","c2","c4","c5"]}}]},{"id":4,"label":"Spoken","digit":6,"drawers":[{"id":"4-1","type":"P6","difficulty":3.3499,"rank":0.9535,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CJ053702","role":"clip1","render":{"description":"Twee mannen die met elkaar praten blijken hetzelfde beleefd te hebben: als ze zich bij een nachtelijke boottocht aan een paal vastklampen, raken ze een witte gedaante aan. Het is een spookverschijning zonder lichaam. De gedaante spoedt zich vervolgens achter de heg langs naar de schuurdeur.","place":"Boornbergum","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25401","original":"Ik praette ris mei in keardel, dy sei: Dêr ha wy hwat bileefd! Wy wurken yn 'e polder. Mei de Feanster boat moest ik fuort by nacht. Ik moest troch hekken.\nIk wie by in hekke. Dêr wie in omstap neist. Ik krige de peal beet, doe taestte ik mei de hân op hwat.\n't Wie in gedaente yn 't wyt, dêr hie 'k op taest.\nFan kleare bare skrik haw ik der op houd mei de bôlleskeppe, dy't ik by my hie. Ik ha der gewoan trochhinne slein. Der siet gjin lichem oan. Doe bin 'k werom stapt.\nDe gedaente stapte achter de hage del en dy is ta de skûrdoar yn stapt.\nDoe't ik goed en wol op 'e boat wie, doe wie dêr ien op 'e boat, dy wie foar my itselde paed lâns kom.\nIk sil wol forbouwereard west ha en hwat wyt om 'e noas.\nDy oare sei tsjin my: \"Hwat sjochstû nuver. …","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"CJ115905","role":"clip2","render":{"description":"Op een bepaalde plaats springt een hek steeds open: een spookhek. Twaalf mannen die 's nachts beurtelings proberen het hek dicht te duwen, zien het hek steeds weer openspringen. Vroeger is er op die plaats iemand vermoord. De geest van de dode doolt nog rond en opent het hek steeds.","place":"Eastermar","prov":"Fr.","year":1977,"code":"SINSAG 0450","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/31213","original":"Op Bennema-state to Hurdegaryp stie de hekke altyd iepen. In kloftsje fan tolve man, dy kommen hjir út 'e omkriten wei, dy woenen dêr mear fan wite. Dy gongen dêr yn 'e nacht hinne en hâldden in weddenskip.\nIen foar ien dienen se de hekke ticht. Mar net sadra hie ien de hekke ticht dien of hy sprong direkt wer iepen. Deselde dy't it ús heit forteld hat wie ien fan 'e tolve. Hy wie de earste. As er de lêste west hie, sa fortelde er, dan hie er it net dwaen doarst. Sadra't er wer by de oare alve mannen stien hie wie de hekke samar út himsels tichtklapt.\nDêr moat ris ien formoarde woarn wêze. Dyselde fynt gjin rêst, en dwaelt dêr sûnt altyd om. Dan giet de hekke iepen, as er ticht is.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c3","story_id":"CJ081906","role":"clip3","render":{"description":"Een turfschipper die steeds opgeschrikt wordt door een naakt kindje achter het schip raadpleegt de dominee. De dominee vraagt het kind - dat allang overleden is - waarom het geen rust kan vinden. Het kind blijkt op die plaats verdronken en vervolgens zonder doodskleed begraven te zijn. Het kind verzoekt de dominee de middelste van drie vrouwen om een doodshemd te vragen. De wens wordt vervuld en de dominee reikt het kind het doodskleed aan met een houten lepel. Nu de wens van het kind vervuld is vindt het rust.","place":"Dokkum","prov":"Fr.","year":1970,"code":"SINSAG 0402","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32618","original":"In Ternaard woonde in turfskipper. Alle kearen as dat skip daar lei dan kwam der in naken kiendsje achter bij 't skip op. De skipper wist niet hoe hij daar mee aan moest. Toen is hij naar doomny gaan en het hem fraagd wat dat was.\nDe doomny kwam op it skip en dy het bidden en hy het it kiend fraagd hwerom it geen rust hat.\nToen het dat kiend seid, hy had gjin bjirhemdtsje.\nHy was daar ferdronken en nu kon hy daar niet rusten.\nIt kiend sei: \"Over it pypke sullen drie dames lopen.\"\nDe middelste moesten se fragen om in bjirhemdsje.\nToen het de skipper henengaan en die het die middelste dame daar om fraagd. En hy het it kregen. En doe het er dat op it turfplak neergooid.\nEn doe het de doomny dat himdtsje dat kiend toereikt met een houten sleef. …","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c4","story_id":"CJ058602","role":"inside","render":{"description":"Het Jankemeer en het Trientsjemeer liggen vlak bij elkaar. In het Jankemeer heeft ene Janke zich verdronken, omdat haar vriend de verkering uitgemaakt had. In het Trientsjemeer is ene Trientsje verdronken. Mensen hebben toen geluiden gehoord. Daar spookt nog altijd een man met een witte rug in een vestje.","place":"Boornbergum","prov":"Fr.","year":1969,"code":"TM 2601","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/26058","original":"By de Skieding hienen jo twa dobben. Oan 'e iene kant fan 'e wei wie de Janke-dobbe, oan 'e oare kant de Tryntsje-dobbe.\nDer wie in sekere Janke, dy hie in feint. Dy feint hie de forkearing mei har út makke, en doe hat Janke har dêr forsûpt. Sa hat dy dobbe de namme fan Janke-dobbe krigen. Sûnt hja har dêr forsûpt hat, spoeket it dêr.\nYn 'e oare dobbe ha se in sekere Tryntsje forsûpt. Tryntsje hat doe lûd jown. Letter hearden se dêr altyd lûden. In man mei in wite rêch yn 't festje spoeket dêr noch altyd om.","lang":"Fries (Woudfries)","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 2.","2 — 12 — 3."],"lock":{"kind":"number3","salt":"e67b9b37a212ac81","accepted_hashes":["91fa562e086603aac094429ed83c1dbb6d55024a160f04ac6756c2500a54584f"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.5242,"rank":1.2875,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ036919","role":"member","render":{"description":"Een dode vrouw is begraven met een te lang doodskleed en blijft na haar dood rondspoken, roepend 'Te lang! Te lang!'. Nadat de dominee haar probleem van haar vernomen heeft, wordt er een stuk van het doodskleed afgescheurd. Haar geest heeft zich nooit meer vertoond.","place":"Buitenpost","prov":"Fr.","year":1968,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22968","original":"Yn 'e Smoarhoeke yn 'e Harkema wie in frou stoarn. Dy hie in bierkleed omkrige yn 'e kiste, dat hie to lang west.\nDoe koe dat minske de rêst net fine. En doe kom se elke joun by de famylje en dan rôp se: \"To lang! To lang!\"\nDoe ha dy lju doomny ophelle en dy hat har oansprutsen. Doe sei se, har bierkleed wie to lang, dêr moest in stik ôf.\nDoe is dêr in stik ôfskuord woarn en sûnt hat se har net wer fortoand.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c2","story_id":"CJ014310","role":"member","render":{"description":"De tweede vrouw van een weduwnaar droeg de kleren van de eerste vrouw. De kinderen zagen echter af en toe hun eerste moeder spoken in de kledingkast. De vader geloofde het niet, maar liet uiteindelijk toch de dominee komen. De geest wilde dat uit haar kleding kleren voor haar kinderen gemaakt werden, en niet dat ze door een andere vrouw gedragen werden.","place":"Buitenpost","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19663","original":"Der leefde in man, dy forlear syn wiif. Hja hie in hiele protte klean fan har sels yn 'e kast. De man troude wer en sei tsjin it twadde wiif: \"Jo kinne dy klean wol drage.\"\nDoe seagen de bern har mem hyltyd wer kommen. Hja spoeke en roan nei de kast ta. Dat gebeurde wit hoe faek. Allinne de bern seagen it en sy fortelden it oan har heit. Mar dy woe 't net leauwe.\n\"Praetsjes\", sei er. Mar de bern bleauwen der by dat har mem nou en dan kom. Dat doe moest er 't op 't lêst ek wol leauwe. Doe helle hy de dûmny der by. Dy spruts it spoek oan.\n\"Hwat is jou bigearte?\" frege er.\n\"Dat de bern klean krije út de klean fan my\", sei se.\n\"Oaren matte se net oan ha.\"\nDat woarde dien en doe kom se net werom.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"CJ109806","role":"intruder","render":{"description":"Man speelt voor dominee, in zijn preek spot hij met alles. Hij doet dit nooit mee, want 's nachts is de duivel aan zijn bed gekomen.","place":"Feanwâlden","prov":"Fr.","year":1974,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/38551","original":"Achter it café yn Feanwâlden stienen froeger banken. Dêr hâldde in kammeraet fan my in preek. Hy wie sabeare doomny. Hy spotte dat it hwat die en hie oeral de gek mei.\nDoe't er dy nachts op bêd lei, kaem de duvel by him. Doe die er it lekken oer de holle hinne, sa binaud waerd er.\nNoait hat er sokke dingen letter wer úthelle.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c4","story_id":"CJ013022","role":"member","render":{"description":"Het gebeurde wel dat gestorvenen terugkwamen als de mensen hun beloftes, die ze gemaakt hadden tijdens het leven van de dode, niet nakwamen. De dominee moest er dan bij komen, om de gestorvene te vragen wat hij wenste.","place":"Buitenpost","prov":"Fr.","year":1966,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19482","original":"It gebeurde wol, fortelde beppe, dat lju dy't stoarn wienen, weromkommen, as de minsken har net hâldden oan 'e bilofte dy't se sokken by har leven dien hienen. Dan moest der in dûmny by komme om sa'n forstoarne to freegjen hwat er winske.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Feanwâlden hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c3","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c2","c4"]}},{"id":"4-3","type":"R4","difficulty":1.2143,"rank":0.7917,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"BOEKV147","role":"top","render":{"description":"Een boer woont in een boerderij waar het spookt. Als een oude soldaat komt bedelen, vraagt de boer of hij wil waken.","place":"Uitdam","prov":"N.-H.","year":1903,"code":"SINSAG 0401","initials":"C.B.","url":"https://www.verhalenbank.nl/items/show/35028","half":"top"},"home":"4-3"},{"id":"c2","story_id":"KEMP173","role":"half","render":{"description":"Gelukkig weet hij dat je tegen spoken brutaal moet optreden en nooit hun zin geven. Hij volgt het spook, maar weigert de opdrachten te vervullen die het spook hem opdraagt. De volgende dag heeft de ambachtsman grijze haren, maar hij is wel in het bezit van een schat. Vanaf nu kan hij van zijn rijkdom leven.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c3","story_id":"CJ015407","role":"half","render":{"description":"Als ze later de varkens gaat voeren, verschijnt de geest van het kind steeds. Het kindje legt steeds de handjes om de varkenstrog.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"},{"id":"c4","story_id":"CJ073804","role":"half","render":{"description":"Toen dreigde Ruerd hem neer te slaan als hij niet wachtte. De ander bleef toen staan. Toen Ruerd bij hem kwam, werd hij door de ander meerdere keren beetgepakt en over de bomen heen gegooid. De volgende dag vonden ze hem bewusteloos en met al zijn ribben gebroken.","half":"bottom","code":"SINSAG 0475"},"home":"4-3"},{"id":"c5","story_id":"BOEKV147","role":"bottom","render":{"description":"Om middernacht ziet de soldaat zes spoken voorbij komen; hoge militairen die met hun sabels een gat gaan graven bij de hooiberg. De spoken halen een ketel met gouden munten omhoog en verstoppen hem weer. 's Ochtends vraagt de soldaat de knecht om mee te helpen graven. Bij de hooiberg vinden ze de ketel met goud en nemen die mee. 's Nachts komen de spoken weer graven, maar vinden niets en keren niet meer terug. De boer is tevreden en biedt de soldaat onderdak en beloning. De soldaat accepteert het onderdak, maar geld heeft hij inmiddels genoeg.","half":"bottom","code":"SINSAG 0401","stain":"zes"},"home":"4-3"},{"id":"c6","story_id":"CJ093904","role":"half","render":{"description":"Hij is verongelukt met een paard en nou ligt zijn schat daar onder de grond. Die oude spookt daar rond en de mensen zijn doodsbang. De oude komt steeds dichterbij.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c7","story_id":"CJ082909","role":"half","render":{"description":"De man kan het niet verdragen en haalt de dominee erbij. De dominee zegt tot de geest 'Als gij van God zijt, kom bij mij, zo gij van de duivel zijt, verwijder u'. De geest verdwijnt en komt nooit meer terug.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘boer’ opnieuw.","Het nummer is SINSAG 0401. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c5","object":"typewriter"},"on_success":{"fuse":["c1","c5"],"type_line":"Verteller: de vorige assistent.","digit":{"value":6,"card":"c1","word":"zes","stained":"c5"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
